cat > scripts/llms.ts <<'EOF'
import { readFileSync, writeFileSync } from "node:fs";

export function renderLlms(input: {
  readme: string;
  designHeadings: string[];
  facts: string;
  repoUrl: string;
}): string {
  const base = input.repoUrl.replace(/\/+$/, "");
  const quote = input.readme
    .split("\n")
    .find((l) => l.startsWith(">"))
    ?.replace(/^>\s?/, "")
    .trim();
  const factLines = input.facts
    .split("\n")
    .map((l) => l.trimEnd())
    .filter((l) => /^[A-Z][A-Z0-9_]* = /.test(l));

  const out = ["# Roster", ""];
  if (quote) out.push(`> ${quote}`, "");
  out.push(
    "## Docs",
    "",
    `- [docs/DESIGN.md](${base}/blob/main/docs/DESIGN.md)`,
    `- [experiments/PREREGISTRATION.md](${base}/blob/main/experiments/PREREGISTRATION.md)`,
    `- [docs/FACTS.md](${base}/blob/main/docs/FACTS.md)`,
    "",
    "## Design sections",
    "",
    ...input.designHeadings.map((h) => `- ${h}`),
    "",
    "## Facts",
    "",
    ...factLines,
    "",
  );
  return out.join("\n");
}

if (import.meta.main) {
  const repoUrl = process.argv[2] ?? "https://github.com/rajkaria/roster";
  const design = readFileSync("docs/DESIGN.md", "utf8");
  const designHeadings = design
    .split("\n")
    .filter((l) => /^##+ /.test(l))
    .map((l) => l.replace(/^#+\s+/, "").trim());
  writeFileSync(
    "llms.txt",
    renderLlms({
      readme: readFileSync("README.md", "utf8"),
      designHeadings,
      facts: readFileSync("docs/FACTS.md", "utf8"),
      repoUrl,
    }),
  );
}
EOF
cat > tests/llms.test.ts <<'EOF'
import { expect, test } from "bun:test";
import { renderLlms } from "../scripts/llms";

const out = renderLlms({
  readme: "# Roster\n\nintro\n\n> The one line.\n> second\n",
  designHeadings: ["Overview", "Setups"],
  facts: "# Facts\n\nA_B = 3 pairs  (source: x)\nC_D = PENDING\nprose line\n",
  repoUrl: "https://github.com/o/r/",
});

test("starts with title and first blockquote line", () => {
  expect(out.startsWith("# Roster\n\n> The one line.\n")).toBe(true);
  expect(out).not.toContain("second");
});

test("docs use absolute GitHub URLs", () => {
  expect(out).toContain("https://github.com/o/r/blob/main/docs/DESIGN.md");
  expect(out).toContain("https://github.com/o/r/blob/main/experiments/PREREGISTRATION.md");
  expect(out).toContain("https://github.com/o/r/blob/main/docs/FACTS.md");
});

test("design headings and facts, PENDING kept", () => {
  expect(out).toContain("## Design sections\n\n- Overview\n- Setups");
  expect(out).toContain("A_B = 3 pairs  (source: x)");
  expect(out).toContain("C_D = PENDING");
  expect(out).not.toContain("prose line");
});
EOF
bun test tests/llms.test.ts 2>&1 | tail -6; bun run typecheck 2>&1 | tail -3; bun test 2>&1 | tail -4

